usage_example:
```hcl
resource "betterado_release_definition" "example" {
  name       = "my-release"
  project_id = var.project_id

  artifact {
    alias      = "_build"
    type       = "Build"
    is_primary = true

    definition_reference = {
      definition = tostring(var.build_definition_id)
      project    = var.project_id
    }
  }

  triggers {
    # Trigger a new release when the build is tagged.
    cd_artifact_trigger {
      artifact_alias                  = "_build"
      use_build_definition_branch     = true
      create_release_on_build_tagging = true

      tag_filter {
        tags = ["stable", "release"]
      }
    }

    # Also trigger when a commit lands on main.
    source_repo_trigger {
      alias          = "_build"
      branch_filters = ["refs/heads/main"]
    }
  }

  environment {
    name = "Production"
    rank = 1

    deploy_phase {
      name       = "Deploy"
      rank       = 1
      phase_type = "agentBasedDeployment"
      queue_id   = var.agent_queue_id
    }

    retention_policy {
      days_to_keep     = 30
      releases_to_keep = 3
      retain_build     = true
    }

    pre_deploy_approval {
      approver {
        id           = "00000000-0000-0000-0000-000000000000"
        is_automated = true
        rank         = 1
      }
    }

    post_deploy_approval {
      approver {
        id           = "00000000-0000-0000-0000-000000000000"
        is_automated = true
        rank         = 1
      }
    }
  }
}
```
